def predict_legacy(repo: str, branch1: str, branch2: str) -> dict:
    base = run_git(repo, "merge-base", branch1, branch2).stdout.strip()
    proc = subprocess.run(
        ["git", "-C", repo, "merge-tree", base, branch1, branch2],
        capture_output=True, text=True,
    )
    if proc.returncode != 0:
        raise RuntimeError(
            f"merge-tree failed (rc={proc.returncode}): {proc.stderr.strip()}"
        )

    # NOTE: the legacy form exits 0 even when conflicts exist; conflicts are
    # detected purely from "<<<<<<<" markers in the merged content.
    # Parse per-file entries; attribute marker lines to the paths of the
    # current entry. Only a new entry header resets the path set -- other
    # unindented lines (@@ diffs, context) belong to the current entry.
    conflicts: dict[str, int] = {}
    current_paths: list[str] = []
    for line in proc.stdout.splitlines():
        m = _PATH_RE.match(line) or _PATH_RE_ALT.match(line)
        if m:
            current_paths.append(m.group(1).strip())
            continue
        if _KNOWN_HEADERS.match(line):
            current_paths = []
            continue
        if line.startswith("<<<<<<<") and current_paths:
            # Markers belong to the last-named path set of this entry.
            for p in current_paths:
                conflicts[p] = conflicts.get(p, 0) + 1
            current_paths = []  # one merged file per entry

    return {
        "mode": "legacy",
        "clean": not conflicts,
        "conflicts": [
            {"path": p, "hunks": n} for p, n in sorted(conflicts.items())
        ],
    }"}]})
